mapper.select:
SELECT BASI.ACCT_SUBJECT_ID prodId, BASI.ACCT_SUBJECT_NAME finprodName, SIV.SERIALNO serialNo, #{INTER_TYPE_SUBJECTINFO,jdbcType=VARCHAR} interType, (case when SIV.XML_STATUS = null then 0 else SIV.XML_STATUS end) xmlStatus, SIV.RETURN_TXT as returnTxt FROM BOK_BOOKSET BB LEFT JOIN BOK_ACCT_SUBJECT_INFO BASI ON BB.ACCT_SUBJECT_ID = BASI.ACCT_SUBJECT_ID AND BASI.ACCT_SUBJECT_TYPE = BB.ACCT_SUBJECT_TYPE LEFT JOIN SZT_INTERF_VALUATION SIV ON SIV.FINPROD_ID = BB.ACCT_SUBJECT_ID AND SIV.INTER_TYPE = #{INTER_TYPE_SUBJECTINFO,jdbcType=VARCHAR} WHERE BB.BOOKSET_TYPE != #{BOOKSET_TYPE_TEMPLATE,jdbcType=VARCHAR}
AND BASI.ACCT_SUBJECT_ID IN
#{item}
and (case when SIV.XML_STATUS = null then 0 else SIV.XML_STATUS end) = #{xmlStatus,jdbcType=VARCHAR}
